function txt(k){return (T[data.prefs.lang]||T.ar)[k]||k}
function icon(id){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('ico');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#i-'+id);svg.append(use);return svg}
