function setPage(p,redraw=true){page=p;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('pageHeading').textContent=txt(p);if(redraw){if(p==='home')renderChannels();if(p==='accounts')renderAccounts();if(p==='chat')renderChat();if(p==='library')renderLibrary();if(p==='schedules'){renderJobSelectors();renderJobs()}}if(p==='chat')syncChat(true);else if(playerRoom)stopPlayer()}
async function call(action,{method='GET',params={},body,timeout=18000,signal}={}){const qs=new URLSearchParams({action,...params});const ctrl=new AbortController(),onAbort=()=>ctrl.abort(),t=setTimeout(()=>ctrl.abort(),timeout);if(signal){if(signal.aborted)ctrl.abort();else signal.addEventListener('abort',onAbort,{once:true})}
 try{const res=await fetch('/api?'+qs,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-KAC-CSRF':api.csrf}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:ctrl.signal});const json=await res.json().catch(()=>({ok:false,error:'خادم أعاد استجابة غير صالحة'}));if(!res.ok||!json.ok)throw new Error(json.error||`HTTP ${res.status}`);return json}finally{clearTimeout(t);if(signal)signal.removeEventListener('abort',onAbort)}}
async function health(){try{const r=await call('health');$('serviceText').textContent=r.configured?txt('ready'):txt('notConfigured');$('serviceDot').classList.toggle('bad',!r.configured);api.chatStorage=!!r.chatStorage;api.background=!!r.background;updateSchedulerStatus();
 const box=$('serverDetails');box.replaceChildren();[[txt('server'),r.configured?txt('ready'):txt('notConfigured')],[txt('chatStorage'),r.chatStorage?txt('ready'):txt('disabled')],['Version',r.version||'—']].forEach(([a,b])=>{const d=node('div','',a+': '+b);box.append(d)});return r}catch(e){$('serviceText').textContent=txt('network');$('serviceDot').classList.add('bad');return null}}
async function currentUser(){try{const r=await call('me');api.accounts=r.accounts||[];api.csrf=r.csrf;api.chatStorage=!!r.chatStorage;api.background=!!r.background;updateSchedulerStatus();api.background=!!r.background;updateSchedulerStatus();renderAccounts();renderStats();renderSendSelector();renderJobSelectors();renderJobs()}catch(e){toast(e.message,'error')}}
function updateSchedulerStatus(){const label=$('schedulerBackendStatus');if(!label)return;
 label.classList.toggle('ready',!!api.background);label.textContent=api.background?(data.prefs.lang==='ar'?'الجدولة الخلفية مفعّلة. الجداول لا تعتمد على بقاء المتصفح مفتوحًا.':'Background scheduling is enabled. Jobs no longer depend on the browser staying open.'):(data.prefs.lang==='ar'?'الجدولة الخلفية غير مفعّلة. إرسال الجداول المحلية قد يتأخر أو يتوقف عند غلق المتصفح.':'Background scheduling is disabled. Local schedules may pause or stop when the browser closes.');}
async function syncServerJob(j,command){
 const r=await call('job_command',{method:'POST',body:{command,id:j.id,job:j},timeout:20000});
 if(r.job){Object.assign(j,r.job);await saveLocal()}
 return r;
}
async function refreshServerJobs(){if(!api.background)return;try{
 const r=await call('jobs',{timeout:30000});
 const incoming=new Map((r.jobs||[]).map(j=>[j.id,j]));
 for(const job of data.jobs){const remote=incoming.get(job.id);if(remote){Object.assign(job,remote);incoming.delete(job.id)}}
 for(const job of incoming.values())data.jobs.push(job);
 await saveLocal();renderJobs();if(page==='accounts')renderAccounts();
 }catch(e){console.warn('Background job sync error',e.message)}}
function refreshJobCountField(){$('jobCount').disabled=$('jobUnlimited').checked}
async function importOfficialToken(e){e.preventDefault();const access=$('tokenAccess').value.trim(),refresh=$('tokenRefresh').value.trim();
 if(!access)return;
 try{await call('import_token',{method:'POST',body:{access_token:access,refresh_token:refresh},timeout:30000});$('tokenImportForm').reset();await currentUser();toast(txt('active'),'good')}
 catch(e){toast(e.message,'error')}
}
