function jobLine(job,str){job.log=(job.log||[]).concat(new Date().toLocaleTimeString(data.prefs.lang)+' — '+String(str)).slice(-25)}
function formatJobWhen(ms){return ms?new Date(ms).toLocaleString(data.prefs.lang==='ar'?'ar-EG':'en-US'):'—'}
const STATUSES={draft:['محفوظ غير مشغل','Saved draft'],pending:['مجدول','Scheduled'],running:['يعمل','Running'],paused:['متوقف مؤقتًا','Paused'],completed:['اكتمل','Completed'],stopped:['متوقف','Stopped'],missed:['فات موعده','Missed'],failed:['فشل','Failed']};
