 if(j.lastError)card.append(node('p','account-last-error',j.lastError));card.append(node('p','',(data.prefs.lang==='ar'?'البداية: ':'Start: ')+formatJobWhen(j.startAt)+(j.nextAt&&j.status==='running'?' · '+(data.prefs.lang==='ar'?'التالي: ':'Next: ')+formatJobWhen(j.nextAt):'')));
