 if(random?(!Number.isInteger(min)||!Number.isInteger(max)||min<3||max>3600||min>max):(!Number.isInteger(interval)||interval<3||interval>3600)){toast('الفاصل لازم يكون من 3 إلى 3600 ثانية، والحد الأدنى أقل من الأقصى','error');return}
 const start=immediately?Date.now():$('jobStart').value?new Date($('jobStart').value).getTime():null,end=$('jobEnd').value?new Date($('jobEnd').value).getTime():0;
 if(!immediately&&start!==null&&(!Number.isFinite(start)||start<Date.now()-2000)){toast('حدد موعد في المستقبل أو اضغط بدء الآن','error');return}
 if(end&&(!Number.isFinite(end)||(start!==null&&end<start))){toast('موعد النهاية لازم بعد البداية','error');return}
 if(data.jobs.length>=500){toast('الحد الأقصى 500 جدول محفوظ محليًا','error');return}
 const j={id:crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),name,slug:channel,account,messages:lines,mode:$('jobMode').value==='random'?'random':'ordered',intervalMs:interval*1000,randomDelay:random,delayMinMs:min*1000,delayMaxMs:max*1000,count,sent:0,attempted:0,failed:0,index:0,startAt:start,endAt:end||null,nextAt:start,status:immediately?'running':start===null?'draft':'pending',createdAt:Date.now(),log:[],inflight:false};
