 const ctrl=new AbortController();jobRequest={id:j.id,controller:ctrl};const ix=j.mode==='random'?(crypto.getRandomValues(new Uint32Array(1))[0]%j.messages.length):(j.index%j.messages.length),content=j.messages[ix];
